    .label-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
    .quality-value { font-size: .84rem; font-weight: 700; color: var(--accent); background: var(--tint); border-radius: 6px; padding: 3px 8px; font-variant-numeric: tabular-nums; }
    input { font: inherit; }
    input[type="file"] {
      width: 100%; min-width: 0; border: 1px solid var(--line); border-radius: 9px;
      padding: 5px; color: var(--muted); font-size: .78rem;
    }
    input::file-selector-button {
      border: 0; border-radius: 5px; background: var(--tint); color: var(--ink);
      padding: 8px; margin-right: 7px; font: inherit; font-weight: 700; cursor: pointer;
    }
    input::file-selector-button:hover { background: #dcebdc; }
    input[type="range"] { width: 100%; margin: 2px 0; accent-color: var(--accent); cursor: pointer; }
    .width-control { position: relative; }
    input[type="number"] {
      width: 100%; border: 1px solid var(--line); border-radius: 9px; color: var(--ink);
      background: var(--surface); padding: 8px 42px 8px 11px;
    }
