      background: var(--tint); border: 1px solid var(--line); border-radius: 12px; overflow: hidden;
    }
    .stage img { display: block; width: 100%; height: 100%; min-height: 0; object-fit: contain; }
    .empty { display: grid; justify-items: center; gap: 12px; color: var(--muted); text-align: center; padding: 16px; font-size: .9rem; }
    .empty-icon { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 12px; background: var(--surface); color: var(--accent); }
    dl { display: grid; grid-template-columns: 1fr 1fr; margin: 0; border: 1px solid var(--line); border-radius: 10px; }
    dl div { padding: 11px 13px; }
    dl div + div { border-left: 1px solid var(--line); }
    dt { color: var(--muted); font-size: .77rem; }
    dd { margin: 3px 0 0; font-weight: 700; font-variant-numeric: tabular-nums; }
