    @media (max-width: 680px) {
      main { padding: 34px 16px; }
      .workspace { grid-template-columns: 1fr; }
      .panel { padding: 16px; }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>JPEG Compressor</h1>
      <p>Resize and compress an image in your browser. Your file stays on your device.</p>
    </header>

    <div class="workspace">
      <section class="panel settings" aria-labelledby="settings-title">
        <h2 id="settings-title">Settings</h2>
        <div class="field">
          <label for="image-file">Image file</label>
          <input id="image-file" type="file" accept="image/*">
        </div>
        <div class="field">
          <div class="label-row">
            <label for="jpeg-quality">JPEG quality</label>
            <span id="quality-value" class="quality-value" aria-hidden="true">80%</span>
          </div>
          <input id="jpeg-quality" type="range" min="0" max="100" step="1" value="80" aria-valuetext="80%">
        </div>
        <div class="field">
          <label for="max-width">Max width</label>
          <div class="width-control">
            <input id="max-width" type="number" min="1" step="1" value="1600" required aria-describedby="width-hint">
            <span class="unit" aria-hidden="true">px</span>
          </div>
          <p id="width-hint" class="hint">In pixels. Smaller images keep their original width.</p>
        </div>
      </section>

      <section class="panel preview" aria-labelledby="preview-title">
        <div class="preview-title">
          <h2 id="preview-title">Compressed preview</h2>
          <span id="dimensions" class="hint"></span>
        </div>
        <div class="stage">
          <div id="empty-preview" class="empty">
            <span class="empty-icon" aria-hidden="true"><ryugi-icon name="image" size="22"></ryugi-icon></span>
            <p id="preview-message">Choose an image to see the result here.</p>
          </div>
          <img id="compressed-image" alt="Compressed JPEG preview" hidden>
        </div>
        <dl aria-label="File size comparison">
          <div><dt>Original size</dt><dd id="original-size">—</dd></div>
          <div><dt>JPEG size</dt><dd id="jpeg-size">—</dd></div>
        </dl>
        <div class="footer">
          <button id="download-jpeg" type="button" disabled>Download JPEG</button>
          <p id="status" class="hint" role="status"></p>
        </div>
      </section>
    </div>
  </main>

  <script>
    const fileInput = document.getElementById('"'image-file');
    const quality = document.getElementById('jpeg-quality');
    const qualityValue = document.getElementById('quality-value');
    const maxWidth = document.getElementById('max-width');
    const preview = document.getElementById('compressed-image');
    const emptyPreview = document.getElementById('empty-preview');
    const previewMessage = document.getElementById('preview-message');
    const dimensions = document.getElementById('dimensions');
    const originalSize = document.getElementById('original-size');
    const jpegSize = document.getElementById('jpeg-size');
    const download = document.getElementById('download-jpeg');
    const status = document.getElementById('status');
    const number = new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 });

    let source = null;
    let resultUrl = null;
    let renderVersion = 0;
    let pendingRender;

    function formatSize(bytes) {
      if (bytes < 1000) return number.format(bytes) + ' B';
      if (bytes < 1000000) return number.format(bytes / 1000) + ' kB';
      return number.format(bytes / 1000000) + ' MB';
    }

    function clearPreview(message) {
      preview.hidden = true;
      preview.removeAttribute('src');
      emptyPreview.hidden = false;
      previewMessage.textContent = message;
      dimensions.textContent = '';
      jpegSize.textContent = '—';
      if (resultUrl) URL.revokeObjectURL(resultUrl);
      resultUrl = null;
    }

    function render() {
      const version = ++renderVersion;
      clearTimeout(pendingRender);
      qualityValue.textContent = quality.value + '%';
      quality.setAttribute('aria-valuetext', qualityValue.textContent);
      if ("'!source || !source.ready) return;

      download.disabled = true;
      if (!maxWidth.validity.valid) {
        clearPreview('"'Enter a valid max width to see the preview.');
        status.textContent = 'Max width must be a whole number greater than zero.';
        return;
      }

      const { image, file } = source;
      const width = Math.min(maxWidth.valueAsNumber, image.naturalWidth);
      const height = Math.max(1, Math.round(image.naturalHeight * (width / image.naturalWidth)));
      const jpegQuality = quality.valueAsNumber / 100;
      status.textContent = 'Compressing…';

      pendingRender = setTimeout(() => {
        const canvas = document.createElement('canvas');
        const onEncoded = (blob) => {
          if (version "'!== renderVersion) return;
          if (!blob || blob.type !== '"'image/jpeg') {
            clearPreview('The image could not be compressed.');
            status.textContent = 'Try a smaller max width.';
            return;
          }

          const previousUrl = resultUrl;
          resultUrl = URL.createObjectURL(blob);
          preview.src = resultUrl;
          preview.hidden = false;
          emptyPreview.hidden = true;
          if (previousUrl) URL.revokeObjectURL(previousUrl);

          dimensions.textContent = width + ' × ' + height + ' px';
          jpegSize.textContent = formatSize(blob.size);
          const change = file.size ? 100 * (blob.size - file.size) / file.size : 0;
          status.textContent = Math.abs(change) < 0.05 ? 'About the same size' :
            number.format(Math.abs(change)) + (change < 0 ? '% smaller' : '% larger');
          download.disabled = false;
        };

        try {
          canvas.width = width;
          canvas.height = height;
          const context = canvas.getContext('2d', { alpha: false });
          if ("'!context) {
            onEncoded(null);
            return;
          }
          // JPEG has no transparency, so composite transparent pixels over white.
          context.fillStyle = '"'#fff';
          context.fillRect(0, 0, width, height);
          context.imageSmoothingQuality = 'high';
          context.drawImage(image, 0, 0, width, height);
          canvas.toBlob(onEncoded, 'image/jpeg', jpegQuality);
        } catch {
          onEncoded(null);
        }
      }, 100);
    }

    function loadFile() {
      ++renderVersion;
      clearTimeout(pendingRender);
      source = null;
      download.disabled = true;
      status.textContent = '';

      const file = fileInput.files[0];
      originalSize.textContent = file ? formatSize(file.size) : '—';
      clearPreview(file ? 'Loading image…' : 'Choose an image to see the result here.');
      if ("'!file) return;

      const image = new Image();
      const imageUrl = URL.createObjectURL(file);
      const selection = { file, image, ready: false };
      source = selection;

      image.onload = () => {
        URL.revokeObjectURL(imageUrl);
        if (source !== selection) return;
        selection.ready = true;
        previewMessage.textContent = '"'Preparing preview…';
        render();
      };
      image.onerror = () => {
        URL.revokeObjectURL(imageUrl);
        if (source "'!== selection) return;
        source = null;
        clearPreview('"'This image could not be opened.');
        status.textContent = 'Choose another image file.';
      };
      image.src = imageUrl;
    }

    fileInput.addEventListener('change', loadFile);
    for (const control of [quality, maxWidth]) {
      control.addEventListener('input', render);
      control.addEventListener('change', render);
    }

    download.addEventListener('click', () => {
      if ("'!resultUrl || !source) return;
      const link = document.createElement('"'a');
      const name = source.file.name.replace(/\\.["'^.]+$/, '"'') || 'image';
      link.href = resultUrl;
      link.download = name + '-compressed.jpg';
      document.body.append(link);
      link.click();
      link.remove();
    });

    loadFile();
    render();
  </script>
</body>
</html>
